fn test_find_count_with_refs_from() {
    let dir = setup_workspace();

    write(
        dir.path().join("source.md"),
        indoc! {"
            # Source

            [child1](child1)

            [child2](child2)
        "},
    )
    .unwrap();
    write(dir.path().join("child1.md"), "# Child One\n\nContent.").unwrap();
    write(dir.path().join("child2.md"), "# Child Two\n\nContent.").unwrap();
    write(dir.path().join("other.md"), "# Other\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--refs-from", "source", "--count"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
}

#[test]
fn test_find_count_with_meta_filter() {
    let dir = setup_workspace();

    write(
        dir.path().join("alpha.md"),
        indoc! {"
            ---
            status: active
            ---
            # Alpha
        "},
    )
    .unwrap();
    write(
        dir.path().join("beta.md"),
        indoc! {"
            ---
            status: archived
            ---
            # Beta
        "},
    )
    .unwrap();
    write(
        dir.path().join("gamma.md"),
        indoc! {"
            ---
            status: active
            ---
            # Gamma
        "},
    )
    .unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--meta", "status=active", "--count"]);

    assert!(success, "stderr: {}", stderr);
