}

#[test]
fn test_find_count_overrides_format() {
    let dir = setup_workspace();

    write(dir.path().join("doc1.md"), "# Document One\n\nContent.").unwrap();
    write(dir.path().join("doc2.md"), "# Document Two\n\nContent.").unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--count", "-f", "json"]);

    assert!(success, "stderr: {}", stderr);
    assert_eq!(stdout.trim(), "2");
    assert!(
        !stdout.contains('{'),
        "count should override format, no JSON expected"
    );
}

#[test]
fn test_find_count_respects_limit() {
    let dir = setup_workspace();

    for i in 1..=5 {
        write(
            dir.path().join(format!("doc{}.md", i)),
            format!("# Document {}\n\nContent.", i),
        )
        .unwrap();
    }

    let (stdout, stderr, success) = run_iwe(dir.path(), &["--limit", "2", "--count"]);

    assert!(success, "stderr: {}", stderr);
    // total still reports the full number of matches, irrespective of limit
    assert_eq!(stdout.trim(), "5");
}
